def word_break(s: str, word_dict: list[str]) -> list[str]:
    if not s: return []
    ws = set(word_dict)
    memo = {}
    def dfs(rem):
        if not rem: return [""]
        if rem in memo: return memo[rem]
        res = []
        for w in ws:
            if rem.startswith(w):
                for t in dfs(rem[len(w):]):
                    res.append(w + (" " + t if t else ""))
        memo[rem] = res
        return res
    return sorted(dfs(s))
